    except Exception as ex:
        errors.append((path, repr(ex))); continue
    h=hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()
    if h != oid:
        modified.append(path)
print('tracked_total', len(head))
print('modified_count', len(modified))
print('deleted_count', len(deleted))
print('error_count', len(errors))
print('\nmodified_first_120')
for p in modified[:120]: print(p)
