    if type(a)!=type(b): return path, type(a).__name__, type(b).__name__
    if isinstance(a,dict):
        for k in sorted(set(a)|set(b)):
            if k not in a or k not in b: return path+'/'+k, a.get(k,'<missing>'), b.get(k,'<missing>')
