    50	/**
    51	 * Resolve site base path from admin base path.
    52	 * Example:
    53	 * - /admin -> '' (site at root)
    54	 * - /ketoandieutam.vn/admin -> /ketoandieutam.vn
    55	 */
    56	function site_base_path_uri(): string
    57	{
    58	  $adminBase = admin_base_path_uri();
    59	  $normalized = rtrim($adminBase, '/');
    60	  if ($normalized === '/admin') {
    61	    return '';
    62	  }
    63	  if (str_ends_with($normalized, '/admin')) {
    64	    $site = substr($normalized, 0, -strlen('/admin'));
    65	    if ($site === '' || $site === '/') {
    66	      return '';
    67	    }
    68	    return $site;
    69	  }
    70	  return '';
    71	}
