    73	/**
    74	 * Start secure session for admin module.
    75	 */
    76	function bootstrap_session(): void
    77	{
    78	  if (session_status() === PHP_SESSION_ACTIVE) {
    79	    return;
    80	  }
    81	
    82	  $isHttps = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off');
    83	  // IMPORTANT:
    84	  // Do not hardcode '/admin' because this project can run under a subfolder
    85	  // (e.g. /ketoandieutam.vn/admin). Hardcoding breaks session cookie scope
    86	  // and causes silent CSRF/login loops.
    87	  $cookiePath = admin_base_path_uri();
    88	  session_set_cookie_params([
    89	    'lifetime' => 0,
    90	    'path' => $cookiePath,
    91	    'domain' => '',
    92	    'secure' => $isHttps,
    93	    'httponly' => true,
    94	    'samesite' => 'Strict',
    95	  ]);
    96	  session_name('ketoan_admin_session');
    97	  session_start();
