   206	  $candidates = [];
   207	  $envPython = trim((string) getenv('KDTD_PYTHON_BIN'));
   208	  if ($envPython !== '') {
   209	    $candidates[] = $envPython;
   210	  }
   211	  $candidates[] = 'python3';
   212	  $candidates[] = 'python';
   213	  $candidates = array_values(array_unique($candidates));
   214	
   215	  $last = null;
